    MOD = 10**9 + 7
    f = create_factorizer_with_sieve(n)

    facts = defaultdict(int)
    for x in range(2, n+1):
        fs = f(x)
        for k, v in fs.items():
            facts[k] += v

    print(reduce(lambda p0, p1: p0*(p1 + 1) % MOD, facts.values(), 1))


