def solve(in_):
    K, S = map(int, next(in_).split())

    ans = 0
    for x in range(K + 1):
        for y in range(x, K + 1):
            z = S - (x + y)
            if y > z:
                break
            if not (0 <= z <= K):
                continue
            # print(x, y, z)
            if x == y == z:
                ans += 1
            elif x == y or y == z or z == x:
                ans += 3
            else:
                ans += 6

    return ans


