def solve():
    N, x = MI()
    A = LI()

    if N == 2:
        d = A[0] + A[1]
        print(max(0, d - x))
        return

    ans = 0

    for i in range(N):
        if A[i] > x:
            ans += A[i] - x
            A[i] = x

    for i in range(1, N-1):
        d1 = A[i] + A[i-1]
        d2 = A[i] + A[i+1]
        if d1 > x and d2 > x:
            if i == N-2 or d1 > d2:
                d = max(d1 - x, d2 - x)
                A[i] -= d
                ans += d
            else:
                A[i] -= (d1 - x)
                ans += (d1 - x)
        elif d1 <= x and d2 <= x:
