        elif d1 > x >= d2:
            A[i] -= (d1-x)
            ans += (d1-x)
            continue
        elif d1 <= x < d2:
            if i == N-2:
                A[i] -= (d2-x)
                ans += (d2-x)
        else:
            raise Exception
    print(ans)



