    h = {}
    for _ in range(M):
        n, m = read_nums()
        if n not in h:
            h[n] = set([m])
        else:
            h[n].add(m)

    # そもそも島1から出られない
    if 1 not in h:
        print('IMPOSSIBLE')
        return

    # 島1 -> i -> N
    for i in h[1]: # O(N)
