def culc_min(arr, tmp_sum, arr_length, turn):
    cnt = 0
    for i in range(arr_length):
        # マイナス計算
        if (i+turn) % 2 == 0:
            if tmp_sum+arr[i] >= 0:
                cnt += abs(arr[i]-(-tmp_sum-1))
                arr[i] = -tmp_sum-1
        #プラス計算
        else:
            if tmp_sum+arr[i] <= 0:
                cnt += abs(arr[i]-(-tmp_sum+1))
                arr[i] = -tmp_sum+1
        tmp_sum += arr[i]

        if i==arr_length-1 and sum(arr[0:arr_length]) == 0:
            cnt += 1
    return cnt   

