def ep(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.perf_counter()
        ret = f(*args, **kwargs)
        e = time.perf_counter()

        ep(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, A):
    def f(s):
        ans = 0
        for i, a in enumerate(A):
            if i == 0:
                ss = a
            else:
                ss = s + a
            if s > 0:
                if ss < 0:
                    pass
                else:
                    ans += ss + 1
                    ss = -1
            else:
                if ss > 0:
                    pass
                else:
                    ans += -ss + 1
                    ss = 1
            s = ss

        return ans
    return min(f(1), f(-1))


