def solve(N, A):
    ranks = [0 for i in range(9)]
    for a in A:
        if a >= 3200:
            ranks[-1] += 1
        else:
            r = a // 400
            ranks[r] += 1
    n_colors = sum([r > 0 for r in ranks[:-1]])
    n_colors_max = n_colors + ranks[-1]
    n_colors_min = max(n_colors, 1)
    return " ".join(map(str, [n_colors_min, n_colors_max]))

