        if c == ')':
            if len(queue) > 0 and queue[-1] == '(':
                queue.pop()
            else:
                queue.append(c)
        else:
            queue.append(c)
    nrp = queue.count(')')
    nlp = queue.count('(')

    ans='('*nrp + s + ')'*nlp
    return ans

