def bellman_ford(N, G, s):
    """ G: edge list [(u, v, c), (u, v, c),...] """
    INF = float('inf')
    dist = [INF] * N
    dist[s] = 0

    for _ in range(N - 1):
        for u, v, c in G:
            if dist[u]!= INF and dist[u] + c < dist[v]:
                dist[v] = dist[u] + c

    negative = [False]*N
    for _ in range(N):
        for u, v, c in G:
            if dist[u] == INF:
                continue
            if dist[u] + c < dist[v]:
                dist[v] = dist[u] + c
                negative[u] = True
            if negative[u]:
                negative[v] = True
    return dist, negative


