def main():
    N, M = map(int, input().split())
    adj = [[] for _ in range(N)]
    rev = [[] for _ in range(N)]
    valid = [0] * M

    for ei, (a, b, c) in enumerate(map(int, input().split()) for _ in range(M)):
        adj[a - 1].append((b - 1, -c, ei))
        rev[b - 1].append((a - 1, -c, ei))

    stack = [0]
    visited = [0] * M
    while stack:
        v = stack.pop()
        for dest, _, ei in adj[v]:
            if visited[ei]:
                continue
            visited[ei] = 1
            valid[ei] += 1
            stack.append(dest)

    stack = [N - 1]
    visited = [0] * M
    while stack:
        v = stack.pop()
        for dest, _, ei in rev[v]:
            if visited[ei]:
                continue
            visited[ei] = 1
            valid[ei] += 1
            stack.append(dest)

    inf = 10**18
    costs = [0] + [inf] * (N - 1)
