def draw_black(rect: list, v: int):
    for ri in range(len(rect)):
        for ci in range(len(rect[ri])):
            if v[2] == 1:
                condition = ci < v[0]
            elif v[2] == 2:
                condition = ci > v[0] - 1
            elif v[2] == 3:
                condition = ri < v[1]
            else:
                condition = ri > v[1] - 1
            if condition:
                rect[ri][ci] = 1


