import sys
from itertools import islice


def _solve(W, H, queries):
    w0 = 0
    h0 = 0
    w1 = W
    h1 = H
    for x, y, a in queries:
        if a == 1:
            w0 = max(w0, x)
        elif a == 2:
            w1 = min(w1, x)
        elif a == 3:
            h0 = max(h0, y)
        # elif a == 4:
        else:
            h1 = min(h1, y)
    return max(0, (w1 - w0)) * max(0, (h1 - h0))


def solve(in_):
    W, H, N = map(int, next(in_).split())
    queries = [tuple(map(int, line.split())) for line in islice(in_, N)]

    return _solve(W, H, queries)


def main():
    answer = solve(sys.stdin)
    print(answer)


if __name__ == '__main__':
    main()

