class UnionFind:
    def __init__(self, N):
        self.par = [-1] * N
    def root(self, x):
        while self.par[x] >= 0:
            x = self.par[x]
        return x
    def union(self, x, y):
        rx = self.root(x)
        ry = self.root(y)
        if rx == ry:
            return
        if -self.par[rx] == -self.par[ry]:
            self.par[ry] -= 1
            self.par[rx] = ry
            return
        if -self.par[rx] > -self.par[ry]:
            rx, ry = ry, rx
        self.par[rx] = ry
    def find(self, x, y):
