        for a, cnt in A:
            S.append(S[-1]+cnt)
            self.A.append(a)
        self.S=S[1:]

    def __getitem__(self, i):
        j=bisect_left(self.S,i+1)
        return self.A[j]

    def sum(self, i):
        """ sum in [0,i) """
        j=bisect_left(self.S,i)
        res=0
        q=0
        for k in range(j):
            res+=self.A[k]*(self.S[k]-q)
            q=self.S[k]
        print(j, res)
        if j>0: res+=self.A[j]*(i-self.S[j-1])
        else: res+=self.A[j]*(i)
        return res

    def __iter__(self):
        l=0
        for i in range(self.S[-1]):
            if i==self.S[l]:
                l+=1
            yield self.A[l]

    def __str__(self):
        return " ".join(list(map(str, self)))

